-- Migración inicial extraída del proyecto remoto vzankvxsjxerlyvffipo (Orby)

-- 1. Catálogos y estados
CREATE TABLE IF NOT EXISTS "public"."estado_cafeteria" (
  "id_estado"     integer               GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "nombre_estado" character varying(60) NOT NULL,
  CONSTRAINT "estado_cafeteria_pkey" PRIMARY KEY (id_estado)
);

ALTER TABLE "public"."estado_cafeteria" ENABLE ROW LEVEL SECURITY;

CREATE TABLE IF NOT EXISTS "public"."estado_comanda" (
  "id_estado"     integer               GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "nombre_estado" character varying(60) NOT NULL,
  CONSTRAINT "estado_comanda_nombre_estado_key" UNIQUE (nombre_estado),
  CONSTRAINT "estado_comanda_pkey" PRIMARY KEY (id_estado)
);

ALTER TABLE "public"."estado_comanda" ENABLE ROW LEVEL SECURITY;

CREATE TABLE IF NOT EXISTS "public"."estado_detalles_comanda" (
  "id_estado"     integer               GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "nombre_estado" character varying(60) NOT NULL,
  CONSTRAINT "estado_detalles_comanda_pkey" PRIMARY KEY (id_estado)
);

ALTER TABLE "public"."estado_detalles_comanda" ENABLE ROW LEVEL SECURITY;

CREATE TABLE IF NOT EXISTS "public"."estado_mesa" (
  "id_estado"     integer               GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "nombre_estado" character varying(40) NOT NULL,
  CONSTRAINT "estado_mesa_pkey" PRIMARY KEY (id_estado)
);

ALTER TABLE "public"."estado_mesa" ENABLE ROW LEVEL SECURITY;

CREATE TABLE IF NOT EXISTS "public"."tipo_notificacion" (
  "id_tipo"     integer               GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "nombre_tipo" character varying(80) NOT NULL,
  CONSTRAINT "tipo_notificacion_pkey" PRIMARY KEY (id_tipo)
);

ALTER TABLE "public"."tipo_notificacion" ENABLE ROW LEVEL SECURITY;

CREATE TABLE IF NOT EXISTS "public"."role" (
  "id_rol"     integer               GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "nombre_rol" character varying(60) NOT NULL,
  CONSTRAINT "role_nombre_rol_key" UNIQUE (nombre_rol),
  CONSTRAINT "role_pkey" PRIMARY KEY (id_rol)
);

ALTER TABLE "public"."role" ENABLE ROW LEVEL SECURITY;

-- 2. Entidades principales
CREATE TABLE IF NOT EXISTS "public"."cafeteria" (
  "id_cafeteria"     uuid                   NOT NULL DEFAULT gen_random_uuid(),
  "nombre_cafeteria" character varying(120) NOT NULL,
  "id_estado"        integer                NOT NULL DEFAULT 1,
  CONSTRAINT "cafeteria_pkey" PRIMARY KEY (id_cafeteria),
  CONSTRAINT "fk_estado" FOREIGN KEY (id_estado) REFERENCES public.estado_cafeteria(id_estado) ON UPDATE CASCADE ON DELETE CASCADE
);

ALTER TABLE "public"."cafeteria" ENABLE ROW LEVEL SECURITY;

CREATE TABLE IF NOT EXISTS "public"."categoria" (
  "id_categoria"     uuid                  NOT NULL DEFAULT gen_random_uuid(),
  "id_cafeteria"     uuid                  NOT NULL,
  "nombre_categoria" character varying(60) NOT NULL,
  CONSTRAINT "categoria_pkey" PRIMARY KEY (id_categoria),
  CONSTRAINT "fk_categoria_cafeteria" FOREIGN KEY (id_cafeteria) REFERENCES public.cafeteria(id_cafeteria) ON DELETE CASCADE
);

ALTER TABLE "public"."categoria" ENABLE ROW LEVEL SECURITY;

CREATE TABLE IF NOT EXISTS "public"."mesa" (
  "id_mesa"      uuid    NOT NULL DEFAULT gen_random_uuid(),
  "id_cafeteria" uuid    NOT NULL,
  "num_mesa"     integer NOT NULL,
  "id_estado"    integer NOT NULL DEFAULT 1,
  CONSTRAINT "fk_cafeteria" FOREIGN KEY (id_cafeteria) REFERENCES public.cafeteria(id_cafeteria) ON UPDATE CASCADE ON DELETE CASCADE,
  CONSTRAINT "fk_estado" FOREIGN KEY (id_estado) REFERENCES public.estado_mesa(id_estado) ON UPDATE CASCADE ON DELETE CASCADE,
  CONSTRAINT "mesa_pkey" PRIMARY KEY (id_mesa),
  CONSTRAINT "uq_mesa_cafeteria" UNIQUE (num_mesa, id_cafeteria)
);

ALTER TABLE "public"."mesa" ENABLE ROW LEVEL SECURITY;

CREATE TABLE IF NOT EXISTS "public"."producto" (
  "id_producto"     uuid                   NOT NULL DEFAULT gen_random_uuid(),
  "id_cafeteria"    uuid                   NOT NULL,
  "id_categoria"    uuid                   NOT NULL,
  "nombre_producto" character varying(120) NOT NULL,
  "descripcion"     character varying(200),
  "precio"          numeric(10,2)          NOT NULL,
  "imagen_url"      character varying(255),
  "estado"          boolean                NOT NULL DEFAULT true,
  CONSTRAINT "fk_producto_cafeteria" FOREIGN KEY (id_cafeteria) REFERENCES public.cafeteria(id_cafeteria) ON DELETE CASCADE,
  CONSTRAINT "fk_producto_categoria" FOREIGN KEY (id_categoria) REFERENCES public.categoria(id_categoria) ON DELETE RESTRICT,
  CONSTRAINT "producto_pkey" PRIMARY KEY (id_producto),
  CONSTRAINT "producto_precio_check" CHECK ((precio >= (0)::numeric))
);

ALTER TABLE "public"."producto" ENABLE ROW LEVEL SECURITY;

CREATE TABLE IF NOT EXISTS "public"."usuario" (
  "id_usuario"   uuid                   NOT NULL,
  "id_cafeteria" uuid                   NOT NULL,
  "nombre"       character varying(140) NOT NULL,
  "foto"         character varying(255),
  "id_rol"       integer                NOT NULL,
  "push_token"   character varying(255),
  CONSTRAINT "fk_cafeteria" FOREIGN KEY (id_cafeteria) REFERENCES public.cafeteria(id_cafeteria) ON UPDATE CASCADE ON DELETE CASCADE,
  CONSTRAINT "fk_roles" FOREIGN KEY (id_rol) REFERENCES public.role(id_rol) ON UPDATE CASCADE ON DELETE CASCADE,
  CONSTRAINT "fk_user_auth" FOREIGN KEY (id_usuario) REFERENCES auth.users(id) ON UPDATE CASCADE ON DELETE CASCADE,
  CONSTRAINT "usuario_pkey" PRIMARY KEY (id_usuario)
);

ALTER TABLE "public"."usuario" ENABLE ROW LEVEL SECURITY;

CREATE TABLE IF NOT EXISTS "public"."comanda" (
  "id_comanda"     uuid                     NOT NULL DEFAULT gen_random_uuid(),
  "id_cafeteria"   uuid                     NOT NULL,
  "id_mesa"        uuid                     NOT NULL,
  "id_usuario"     uuid                     NOT NULL,
  "id_estado"      integer                  NOT NULL DEFAULT 1,
  "total"          numeric(10,2)            DEFAULT 0.00,
  "fecha_creacion" timestamp with time zone DEFAULT now(),
  CONSTRAINT "comanda_pkey" PRIMARY KEY (id_comanda),
  CONSTRAINT "fk_comanda_cafeteria" FOREIGN KEY (id_cafeteria) REFERENCES public.cafeteria(id_cafeteria) ON UPDATE CASCADE ON DELETE CASCADE,
  CONSTRAINT "fk_estado_comanda" FOREIGN KEY (id_estado) REFERENCES public.estado_comanda(id_estado),
  CONSTRAINT "fk_comanda_mesa" FOREIGN KEY (id_mesa) REFERENCES public.mesa(id_mesa) ON UPDATE CASCADE ON DELETE CASCADE,
  CONSTRAINT "fk_comanda_usuario" FOREIGN KEY (id_usuario) REFERENCES public.usuario(id_usuario) ON UPDATE CASCADE ON DELETE CASCADE
);

ALTER TABLE "public"."comanda" ENABLE ROW LEVEL SECURITY;

CREATE TABLE IF NOT EXISTS "public"."detalle_comanda" (
  "id_detalle"       uuid                   NOT NULL DEFAULT gen_random_uuid(),
  "id_comanda"       uuid                   NOT NULL,
  "id_producto"      uuid                   NOT NULL,
  "cantidad"         smallint               NOT NULL,
  "precio_unitario"  numeric(10,2)          NOT NULL,
  "especificaciones" character varying(255),
  "tiempo_estimado"  smallint,
  "id_estado"        integer                NOT NULL DEFAULT 1,
  CONSTRAINT "detalle_comanda_cantidad_check" CHECK ((cantidad > 0)),
  CONSTRAINT "detalle_comanda_pkey" PRIMARY KEY (id_detalle),
  CONSTRAINT "fk_detalle_comanda" FOREIGN KEY (id_comanda) REFERENCES public.comanda(id_comanda) ON UPDATE CASCADE ON DELETE CASCADE,
  CONSTRAINT "fk_estado_detalle" FOREIGN KEY (id_estado) REFERENCES public.estado_detalles_comanda(id_estado),
  CONSTRAINT "fk_detalle_producto" FOREIGN KEY (id_producto) REFERENCES public.producto(id_producto)
);

ALTER TABLE "public"."detalle_comanda" ENABLE ROW LEVEL SECURITY;

CREATE TABLE IF NOT EXISTS "public"."notificacion" (
  "id_notificacion" uuid                     NOT NULL DEFAULT gen_random_uuid(),
  "id_cafeteria"    uuid                     NOT NULL,
  "id_usuario"      uuid                     NOT NULL,
  "id_comanda"      uuid                     NOT NULL,
  "id_tipo"         integer                  NOT NULL,
  "leida"           boolean                  NOT NULL DEFAULT false,
  "fecha_creacion"  timestamp with time zone DEFAULT now(),
  CONSTRAINT "fk_notificacion_cafeteria" FOREIGN KEY (id_cafeteria) REFERENCES public.cafeteria(id_cafeteria) ON DELETE CASCADE,
  CONSTRAINT "fk_notificacion_comanda" FOREIGN KEY (id_comanda) REFERENCES public.comanda(id_comanda) ON DELETE CASCADE,
  CONSTRAINT "notificacion_pkey" PRIMARY KEY (id_notificacion),
  CONSTRAINT "fk_tipo_alerta" FOREIGN KEY (id_tipo) REFERENCES public.tipo_notificacion(id_tipo),
  CONSTRAINT "fk_notificacion_usuario" FOREIGN KEY (id_usuario) REFERENCES public.usuario(id_usuario) ON DELETE CASCADE
);

ALTER TABLE "public"."notificacion" ENABLE ROW LEVEL SECURITY;

-- 3. Función y trigger para creación de usuarios desde Auth
CREATE OR REPLACE FUNCTION public.handle_new_user()
  RETURNS TRIGGER
  LANGUAGE plpgsql
  SECURITY DEFINER
  AS $function$
DECLARE
  v_id_cafeteria UUID;
  v_id_rol INT;
BEGIN
  -- 1. Buscar el ID del rol en la tabla 'role' usando el texto enviado en metadatos
  SELECT id_rol INTO v_id_rol 
  FROM public.role 
  WHERE nombre_rol = new.raw_user_meta_data->>'rol' 
  LIMIT 1;

  -- 2. Evaluar si es un nuevo administrador creando su cafetería o un empleado
  IF new.raw_user_meta_data->>'rol' = 'administrador' THEN
    INSERT INTO public.cafeteria (nombre_cafeteria)
    VALUES (new.raw_user_meta_data->>'nombre_cafeteria')
    RETURNING id_cafeteria INTO v_id_cafeteria;
  ELSE
    v_id_cafeteria := (new.raw_user_meta_data->>'id_cafeteria')::uuid;
  END IF;

  -- 3. Insertar el registro final en la tabla 'usuario'
  INSERT INTO public.usuario (id_usuario, id_cafeteria, nombre, id_rol)
  VALUES (
    new.id,
    v_id_cafeteria,
    new.raw_user_meta_data->>'nombre', 
    v_id_rol
  );
  
  RETURN new;
END;
$function$;

DROP TRIGGER IF EXISTS on_auth_user_created ON auth.users;
CREATE TRIGGER on_auth_user_created
  AFTER INSERT ON auth.users
  FOR EACH ROW
  EXECUTE FUNCTION public.handle_new_user();

-- 4. Datos iniciales de catálogos (ID 1 = estado activo/inicial por defecto)
INSERT INTO "public"."estado_cafeteria" ("id_estado", "nombre_estado")
OVERRIDING SYSTEM VALUE VALUES
  (1, 'activa'),
  (2, 'inactiva'),
  (3, 'suspendida')
ON CONFLICT ("id_estado") DO UPDATE SET "nombre_estado" = EXCLUDED."nombre_estado";

SELECT setval(pg_get_serial_sequence('public.estado_cafeteria', 'id_estado'), (SELECT MAX(id_estado) FROM public.estado_cafeteria));

